"use client";

import { useRef, useEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { storyMemories } from '@/data/memories';

gsap.registerPlugin(ScrollTrigger);

export default function OurStoryScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const chapterRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    // Header reveal
    gsap.fromTo(headerRef.current,
      { opacity: 0, y: 30 },
      {
        opacity: 1, 
        y: 0, 
        duration: 1,
        ease: "power2.out",
        scrollTrigger: {
          trigger: headerRef.current,
          start: "top 80%",
        }
      }
    );

    // Chapters reveal
    chapterRefs.current.forEach((chapter, index) => {
      if (!chapter) return;
      
      const image = chapter.querySelector('.story-image');
      const content = chapter.querySelector('.story-content');
      const isEven = index % 2 === 0;

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: chapter,
          start: "top 75%",
        }
      });

      tl.fromTo(image,
        { opacity: 0, x: isEven ? -50 : 50 },
        { opacity: 1, x: 0, duration: 1.2, ease: "power3.out" }
      )
      .fromTo(content,
        { opacity: 0, y: 30 },
        { opacity: 1, y: 0, duration: 1, ease: "power2.out" },
        "-=0.8"
      );
    });

    return () => {
      ScrollTrigger.getAll().forEach(t => t.kill());
    };
  }, []);

  return (
    <section ref={containerRef} className="py-32 px-6 bg-midnight text-warm-ivory relative overflow-hidden">
      
      {/* Section Header */}
      <div ref={headerRef} className="text-center mb-32 max-w-3xl mx-auto">
        <h2 className="text-sm tracking-[0.3em] text-muted-gold uppercase mb-4">Our Little Universe</h2>
        <h3 className="text-3xl md:text-5xl font-serif leading-tight">
          Every year, another chapter.<br/>Every memory, another reason to smile.
        </h3>
      </div>

      {/* Chapters */}
      <div className="max-w-6xl mx-auto flex flex-col gap-32 md:gap-48">
        {storyMemories.map((memory, index) => {
          const isEven = index % 2 === 0;
          return (
            <div 
              key={memory.id} 
              ref={el => { chapterRefs.current[index] = el; }}
              className={`flex flex-col ${isEven ? 'md:flex-row' : 'md:flex-row-reverse'} items-center gap-12 md:gap-20`}
            >
              {/* Image Area */}
              <div className="w-full md:w-1/2 story-image">
                <div className="relative aspect-[4/5] md:aspect-square rounded-2xl overflow-hidden border border-warm-ivory/10 shadow-2xl">
                  <div className="absolute inset-0 bg-gradient-to-tr from-deep-burgundy/20 to-midnight mix-blend-overlay z-10" />
                  <div className="w-full h-full bg-[#1a1a24] flex items-center justify-center text-warm-ivory/30 text-sm tracking-widest border border-dashed border-warm-ivory/20">
                    [ MEDIA: {memory.year} ]
                  </div>
                  {memory.location && (
                    <div className="absolute bottom-4 left-4 z-20 bg-midnight/60 backdrop-blur-sm px-4 py-2 rounded-full text-xs tracking-wider border border-warm-ivory/10">
                      📍 {memory.location}
                    </div>
                  )}
                </div>
              </div>

              {/* Content Area */}
              <div className="w-full md:w-1/2 flex flex-col story-content">
                <span className="text-dusty-rose text-6xl md:text-8xl font-serif opacity-30 -mb-6 md:-mb-8 z-0">
                  {memory.year}
                </span>
                <h4 className="text-3xl md:text-4xl font-serif mb-6 z-10 text-warm-ivory">
                  {memory.chapterTitle}
                </h4>
                <p className="text-warm-ivory/70 text-lg leading-relaxed font-light mb-8 z-10">
                  {memory.description}
                </p>
                {memory.caption && (
                  <p className="text-sm font-serif italic text-muted-gold border-l-2 border-muted-gold/30 pl-4">
                    {memory.caption}
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
      
    </section>
  );
}
