"use client";

import { useRef, useEffect } from 'react';
import gsap from 'gsap';
import { siteConfig } from '@/data/site-config';

export default function HeroScene() {
  const containerRef = useRef<HTMLDivElement>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const subRef = useRef<HTMLParagraphElement>(null);
  const captionRef = useRef<HTMLParagraphElement>(null);
  const imageRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const tl = gsap.timeline({ delay: 0.5 });

    // Ensure initial states
    gsap.set([headingRef.current, subRef.current, captionRef.current], { 
      opacity: 0, 
      y: 20 
    });
    
    gsap.set(imageRef.current, { 
      opacity: 0, 
      scale: 1.05 
    });

    // Cinematic Reveal
    tl.to(imageRef.current, {
      opacity: 1,
      scale: 1,
      duration: 2.5,
      ease: "power3.out"
    })
    .to(headingRef.current, {
      opacity: 1,
      y: 0,
      duration: 1.2,
      ease: "power2.out"
    }, "-=1.5")
    .to(subRef.current, {
      opacity: 1,
      y: 0,
      duration: 1,
      ease: "power2.out"
    }, "-=0.8")
    .to(captionRef.current, {
      opacity: 0.6,
      y: 0,
      duration: 1,
      ease: "power2.out"
    }, "-=0.6");

    return () => {
      tl.kill();
    };
  }, []);

  return (
    <section 
      ref={containerRef}
      className="relative min-h-screen w-full flex flex-col md:flex-row items-center justify-center overflow-hidden bg-midnight px-6 py-20"
    >
      {/* Editorial Layout: Image on Desktop right, Text on Desktop left */}
      
      <div className="w-full md:w-1/2 flex flex-col items-center md:items-start text-center md:text-left z-10 md:pl-[10%] mb-12 md:mb-0">
        <h1 
          ref={headingRef} 
          className="text-4xl md:text-6xl lg:text-7xl font-serif text-warm-ivory leading-tight mb-6"
        >
          {siteConfig.hero.heading}
        </h1>
        
        <p 
          ref={subRef} 
          className="text-lg md:text-xl text-warm-ivory/80 font-light max-w-md leading-relaxed mb-10"
        >
          {siteConfig.hero.subheading}
        </p>

        <p 
          ref={captionRef} 
          className="text-sm uppercase tracking-[0.2em] text-muted-gold font-serif italic"
        >
          {siteConfig.hero.caption}
        </p>
      </div>

      {/* Media Area */}
      <div className="w-full md:w-1/2 h-[50vh] md:h-[80vh] flex items-center justify-center px-4 md:pr-[10%]">
        <div 
          ref={imageRef}
          className="relative w-full h-full max-w-lg rounded-2xl overflow-hidden border border-warm-ivory/10 shadow-2xl"
        >
          {/* Placeholder for the real image/video. Uses a CSS gradient temporarily. */}
          <div className="absolute inset-0 bg-gradient-to-tr from-deep-burgundy/30 to-midnight mix-blend-overlay z-10" />
          <div className="w-full h-full bg-[#1a1a24] flex items-center justify-center text-warm-ivory/30 text-sm tracking-widest border border-dashed border-warm-ivory/20">
            [ HERO MEDIA PLACEHOLDER ]
          </div>
        </div>
      </div>
      
    </section>
  );
}
